import express from "express";
import pg from "pg";
import path from "node:path";
import fs from "node:fs/promises";
import { fileURLToPath } from "node:url";

const app = express();
const PORT = process.env.PORT || 3000;
const API_KEY = process.env.API_FOOTBALL_KEY;
const TELEGRAM_BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;
const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;
const BASE_URL = "https://v3.football.api-sports.io";
const ROOT = path.dirname(fileURLToPath(import.meta.url));

app.use(express.json({ limit: "500kb" }));
// WinScope arayüzü bu dosyaya gömülüdür; dağıtım için public/index.html gerekmez.
const EMBEDDED_INDEX_HTML = Buffer.from("", "base64").toString("utf8");
app.get("/", async (_req, res) => {
  try {
    const html = await fs.readFile(path.join(ROOT, "index.html"), "utf8");
    return res.type("html").send(html);
  } catch {
    return res.type("html").send(EMBEDDED_INDEX_HTML);
  }
});
app.use(express.static(path.join(ROOT, "public")));

const providerCache = new Map();
const providerInFlight = new Map();
const archives = { analyses: [], coupons: [] };
const predictionTracking = [];
const livePredictionTracking = [];
const dailyMarketTracking = [];
const dailyAnalysisJobs = new Map();
const dailyAnalysisRunCache = new Map();
const { Pool } = pg;
const databasePool = process.env.DATABASE_URL
  ? new Pool({ connectionString: process.env.DATABASE_URL, ssl: /localhost|127\.0\.0\.1/.test(process.env.DATABASE_URL) ? false : { rejectUnauthorized: false } })
  : null;
let archiveDatabaseReady = Promise.resolve();
if (databasePool) {
  archiveDatabaseReady = (async () => {
    try {
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_archive (
        id BIGSERIAL PRIMARY KEY,
        category TEXT NOT NULL CHECK (category IN ('analysis','coupon')),
        payload JSONB NOT NULL,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_archive_category_id_idx ON winscope_archive(category, id DESC)");
      // Ham fikstur arşivi: API-Football'dan gelen her fixture kalıcı tutulur.
      // Fixture ID tekildir; sonraki API cevapları aynı satırı günceller, eski kayıt silinmez.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_fixture_archive (
        fixture_id BIGINT PRIMARY KEY,
        match_date DATE,
        kickoff_at TIMESTAMPTZ,
        status TEXT,
        home_team TEXT,
        away_team TEXT,
        league TEXT,
        payload JSONB NOT NULL,
        source_endpoint TEXT,
        first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_fixture_archive_date_idx ON winscope_fixture_archive(match_date DESC)");
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_fixture_archive_status_idx ON winscope_fixture_archive(status)");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_fixture_odds_archive (
        id BIGSERIAL PRIMARY KEY,
        fixture_id BIGINT NOT NULL,
        payload JSONB NOT NULL,
        source_endpoint TEXT,
        captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_fixture_odds_archive_fixture_idx ON winscope_fixture_odds_archive(fixture_id, captured_at DESC)");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_daily_analysis_coupon_sessions (
        match_date DATE NOT NULL,
        session TEXT NOT NULL CHECK (session IN ('early','second')),
        picks JSONB NOT NULL,
        telegram_message_id BIGINT,
        sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY(match_date, session)
      )`);
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_daily_analysis_runs (
        match_date DATE PRIMARY KEY,
        status TEXT NOT NULL,
        result JSONB,
        error TEXT,
        started_at TIMESTAMPTZ,
        finished_at TIMESTAMPTZ,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      // AI kupon türleri early/second seans tablosundan ayrıdır; eski CHECK kısıtı
      // ai_reliable / ai_alternative / ai_surprise kayıtlarını reddediyordu.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_ai_coupon_sessions (
        match_date DATE NOT NULL,
        session TEXT NOT NULL CHECK (session IN ('ai_reliable','ai_alternative','ai_surprise')),
        picks JSONB NOT NULL,
        telegram_message_id BIGINT,
        sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY(match_date, session)
      )`);
      // Günün otomatik maç önü kuponu: restart sonrası da aynı gün tekrar gönderilmesini önler.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_auto_coupon_runs (
        match_date DATE NOT NULL,
        coupon_type TEXT NOT NULL,
        status TEXT NOT NULL,
        attempts INTEGER NOT NULL DEFAULT 0,
        last_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        telegram_message_id BIGINT,
        result JSONB,
        error TEXT,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY(match_date, coupon_type)
      )`);

      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_reversal_predictions (
        fixture_id BIGINT NOT NULL,
        scenario TEXT NOT NULL CHECK (scenario IN ('1/2','2/1')),
        match_date DATE NOT NULL,
        kickoff_at TIMESTAMPTZ,
        league TEXT,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        bookmaker TEXT NOT NULL,
        captured_home_prob NUMERIC,
        captured_draw_prob NUMERIC,
        captured_away_prob NUMERIC,
        score NUMERIC NOT NULL DEFAULT 0,
        reason JSONB NOT NULL DEFAULT '{}'::jsonb,
        halftime_score TEXT,
        final_score TEXT,
        actual_htft TEXT,
        outcome TEXT CHECK (outcome IN ('won','lost')),
        settled_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY(fixture_id, scenario)
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_reversal_date_idx ON winscope_reversal_predictions(match_date, scenario, kickoff_at)");
      // Ayrı gölge test tablosu: mevcut 1/2 ve 2/1 motor kayıtlarına dokunmaz.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_reversal_lab_predictions (
        fixture_id BIGINT NOT NULL, scenario TEXT NOT NULL CHECK (scenario IN ('1/2','2/1')),
        match_date DATE NOT NULL, kickoff_at TIMESTAMPTZ, league TEXT, home_team TEXT NOT NULL, away_team TEXT NOT NULL,
        bookmaker TEXT, score NUMERIC NOT NULL DEFAULT 0, features JSONB NOT NULL DEFAULT '{}'::jsonb,
        halftime_score TEXT, final_score TEXT, actual_htft TEXT,
        outcome TEXT CHECK (outcome IN ('won','lost')), settled_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(fixture_id,scenario)
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_reversal_lab_date_idx ON winscope_reversal_lab_predictions(match_date,scenario,kickoff_at)");

      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_surprise_scenarios (
        fixture_id BIGINT PRIMARY KEY,
        match_date TEXT NOT NULL,
        kickoff_at TIMESTAMPTZ,
        league TEXT,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        opening_odds JSONB NOT NULL DEFAULT '{}'::jsonb,
        closing_odds JSONB NOT NULL DEFAULT '{}'::jsonb,
        final_score TEXT,
        halftime_score TEXT,
        htft_result TEXT,
        over25_outcome BOOLEAN,
        btts_outcome BOOLEAN,
        settled BOOLEAN NOT NULL DEFAULT FALSE,
        last_snapshot_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        settled_at TIMESTAMPTZ
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_surprise_date_idx ON winscope_surprise_scenarios(match_date, kickoff_at)");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_coupon_predictions (
        tracking_id BIGSERIAL PRIMARY KEY,
        coupon_key TEXT NOT NULL,
        coupon_type TEXT NOT NULL,
        fixture_id BIGINT NOT NULL,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        league TEXT,
        market TEXT NOT NULL,
        start_score TEXT,
        actual_score TEXT,
        outcome TEXT,
        match_date TEXT,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        settled_at TIMESTAMPTZ,
        telegram_notified_at TIMESTAMPTZ,
        UNIQUE(coupon_key, fixture_id, market)
      )`);
      await databasePool.query("ALTER TABLE winscope_coupon_predictions ADD COLUMN IF NOT EXISTS telegram_notified_at TIMESTAMPTZ");
      await databasePool.query("ALTER TABLE winscope_coupon_predictions ADD COLUMN IF NOT EXISTS settlement_checked_at TIMESTAMPTZ");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_coupon_result_notifications (
        fixture_id BIGINT NOT NULL,
        market_key TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'sending',
        telegram_message_id BIGINT,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        sent_at TIMESTAMPTZ,
        PRIMARY KEY (fixture_id, market_key)
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_coupon_predictions_created_idx ON winscope_coupon_predictions(created_at DESC)");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_daily_market_predictions (
        fixture_id BIGINT NOT NULL,
        match_date TEXT NOT NULL,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        league TEXT,
        market TEXT NOT NULL,
        actual_score TEXT,
        outcome TEXT,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        settled_at TIMESTAMPTZ,
        PRIMARY KEY (fixture_id, market)
      )`);
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_score6_predictions (
        fixture_id BIGINT PRIMARY KEY,
        match_date TEXT NOT NULL,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        league TEXT,
        predicted_ht TEXT,
        predicted_ft TEXT,
        alternative_ft TEXT,
        predicted_htft TEXT,
        six_plus_candidate BOOLEAN NOT NULL DEFAULT FALSE,
        six_plus_probability NUMERIC,
        actual_ht TEXT,
        actual_ft TEXT,
        actual_htft TEXT,
        exact_ht BOOLEAN,
        exact_ft BOOLEAN,
        exact_alternative_ft BOOLEAN,
        six_plus_won BOOLEAN,
        settled BOOLEAN NOT NULL DEFAULT FALSE,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        settled_at TIMESTAMPTZ
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_score6_date_idx ON winscope_score6_predictions(match_date, settled)");
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_daily_market_date_idx ON winscope_daily_market_predictions(match_date, market, outcome)");
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_predictions (
        fixture_id BIGINT PRIMARY KEY, home_team TEXT NOT NULL, away_team TEXT NOT NULL,
        predicted_ht TEXT, predicted_ft TEXT, alternative_ft TEXT,
        actual_ht TEXT, actual_ft TEXT, exact_ft BOOLEAN, exact_ht BOOLEAN,
        match_date TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), settled_at TIMESTAMPTZ
      )`);
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_telegram_fixture_sent (
        fixture_id BIGINT PRIMARY KEY,
        match_date DATE,
        coupon_type TEXT,
        sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      // Telegram tekrar engeli artık maç + kupon türü + market bazındadır.
      // Eski fixture-only tablo korunur; geçmiş kayıtlar silinmez veya yanlışlıkla
      // farklı marketlerin gönderimini engellemez.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_telegram_delivery_sent (
        fixture_id BIGINT NOT NULL,
        coupon_type TEXT NOT NULL,
        market TEXT NOT NULL,
        match_date DATE,
        telegram_message_id BIGINT,
        sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY (fixture_id, coupon_type, market)
      )`);
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_live_predictions (
        prediction_id BIGSERIAL PRIMARY KEY,
        fixture_id BIGINT NOT NULL, home_team TEXT NOT NULL, away_team TEXT NOT NULL,
        market TEXT NOT NULL, signal_key TEXT NOT NULL, league TEXT, match_date TEXT, start_score TEXT, minute INTEGER,
        actual_score TEXT, outcome TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        settled_at TIMESTAMPTZ
      )`);
      // Gol bildirimi takibi süreç yeniden başlasa da kaybolmasın.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_goal_alert_tracking (
        fixture_id BIGINT PRIMARY KEY,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        league TEXT,
        source_label TEXT,
        last_score TEXT NOT NULL DEFAULT '0-0',
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      // Early first-half goal picks are tracked separately from ordinary live alerts.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_early_goal_predictions (
        fixture_id BIGINT PRIMARY KEY,
        match_date DATE,
        home_team TEXT NOT NULL,
        away_team TEXT NOT NULL,
        league TEXT,
        market TEXT NOT NULL,
        selected_side TEXT,
        analysis_score NUMERIC,
        start_score TEXT NOT NULL DEFAULT '0-0',
        current_score TEXT NOT NULL DEFAULT '0-0',
        outcome TEXT CHECK (outcome IN ('won','lost')),
        settled_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_early_goal_predictions_date_idx ON winscope_early_goal_predictions(match_date, outcome)");
      // Backfill schema for databases created by older deployments. CREATE TABLE IF NOT EXISTS
      // does not add columns to an existing table, which previously broke weekly tracking.
      await databasePool.query(`ALTER TABLE winscope_live_predictions
        ADD COLUMN IF NOT EXISTS prediction_id BIGSERIAL,
        ADD COLUMN IF NOT EXISTS fixture_id BIGINT,
        ADD COLUMN IF NOT EXISTS home_team TEXT,
        ADD COLUMN IF NOT EXISTS away_team TEXT,
        ADD COLUMN IF NOT EXISTS market TEXT,
        ADD COLUMN IF NOT EXISTS signal_key TEXT,
        ADD COLUMN IF NOT EXISTS league TEXT,
        ADD COLUMN IF NOT EXISTS match_date TEXT,
        ADD COLUMN IF NOT EXISTS start_score TEXT,
        ADD COLUMN IF NOT EXISTS minute INTEGER,
        ADD COLUMN IF NOT EXISTS actual_score TEXT,
        ADD COLUMN IF NOT EXISTS outcome TEXT,
        ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW(),
        ADD COLUMN IF NOT EXISTS settled_at TIMESTAMPTZ`);
      // Existing databases may already have signal_key as NOT NULL. Backfill old rows
      // before enforcing the constraint so tracking writes never fail on a missing key.
      await databasePool.query(`UPDATE winscope_live_predictions
        SET signal_key = COALESCE(NULLIF(signal_key, ''), fixture_id::TEXT || ':' || COALESCE(market, 'unknown'))
        WHERE signal_key IS NULL OR signal_key = ''`);
      await databasePool.query(`ALTER TABLE winscope_live_predictions ALTER COLUMN signal_key SET NOT NULL`);
      // Migrate older installs where fixture_id was the primary key so one match can
      // store multiple distinct markets without losing existing tracking rows.
      await databasePool.query(`ALTER TABLE winscope_live_predictions ADD COLUMN IF NOT EXISTS prediction_id BIGSERIAL`);
      await databasePool.query(`DO $$ DECLARE pk_name TEXT; BEGIN
        SELECT conname INTO pk_name FROM pg_constraint
        WHERE conrelid='winscope_live_predictions'::regclass AND contype='p' LIMIT 1;
        IF pk_name IS NOT NULL THEN EXECUTE format('ALTER TABLE winscope_live_predictions DROP CONSTRAINT %I', pk_name); END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='winscope_live_predictions'::regclass AND contype='p') THEN
          ALTER TABLE winscope_live_predictions ADD CONSTRAINT winscope_live_predictions_pkey PRIMARY KEY (prediction_id);
        END IF;
      END $$`);
      await databasePool.query("CREATE UNIQUE INDEX IF NOT EXISTS winscope_live_predictions_fixture_market_uidx ON winscope_live_predictions(fixture_id, market)")
      // SCORE SHOT: tamamen bağımsız tahmin ve sonuç tablosu; mevcut motor tablolarına yazmaz.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_score_shot_predictions (
        fixture_id BIGINT NOT NULL, match_date DATE NOT NULL, kickoff_at TIMESTAMPTZ,
        league_id INTEGER, league TEXT, home_team TEXT NOT NULL, away_team TEXT NOT NULL,
        predicted_ht TEXT NOT NULL, predicted_ft TEXT NOT NULL,
        top_scores JSONB NOT NULL DEFAULT '[]'::jsonb, model_data JSONB NOT NULL DEFAULT '{}'::jsonb,
        features JSONB NOT NULL DEFAULT '{}'::jsonb,
        selection_score NUMERIC NOT NULL DEFAULT 0, exact_probability NUMERIC,
        actual_ht TEXT, actual_ft TEXT, ht_hit BOOLEAN, ft_hit BOOLEAN,
        top3_hit BOOLEAN, settled_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY(fixture_id, match_date)
      )`);
      // Score Shot schema migration: eski kurulumlarda tablo CREATE TABLE IF NOT EXISTS
      // nedeniyle güncellenmiyordu. Sonuç/performans sorgularının kullandığı alanları
      // mevcut Score Shot tablosuna güvenli biçimde ekle; diğer WinScope tablolarına dokunma.
      await databasePool.query(`ALTER TABLE winscope_score_shot_predictions
        ADD COLUMN IF NOT EXISTS fixture_id BIGINT,
        ADD COLUMN IF NOT EXISTS match_date DATE,
        ADD COLUMN IF NOT EXISTS kickoff_at TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS league_id INTEGER,
        ADD COLUMN IF NOT EXISTS league TEXT,
        ADD COLUMN IF NOT EXISTS home_team TEXT,
        ADD COLUMN IF NOT EXISTS away_team TEXT,
        ADD COLUMN IF NOT EXISTS predicted_ht TEXT,
        ADD COLUMN IF NOT EXISTS predicted_ft TEXT,
        ADD COLUMN IF NOT EXISTS top_scores JSONB DEFAULT '[]'::jsonb,
        ADD COLUMN IF NOT EXISTS model_data JSONB DEFAULT '{}'::jsonb,
        ADD COLUMN IF NOT EXISTS features JSONB DEFAULT '{}'::jsonb,
        ADD COLUMN IF NOT EXISTS selection_score NUMERIC DEFAULT 0,
        ADD COLUMN IF NOT EXISTS exact_probability NUMERIC,
        ADD COLUMN IF NOT EXISTS actual_ht TEXT,
        ADD COLUMN IF NOT EXISTS actual_ft TEXT,
        ADD COLUMN IF NOT EXISTS ht_hit BOOLEAN,
        ADD COLUMN IF NOT EXISTS ft_hit BOOLEAN,
        ADD COLUMN IF NOT EXISTS top3_hit BOOLEAN,
        ADD COLUMN IF NOT EXISTS settled_at TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW()`);
      // Older Score Shot tables already had a NOT NULL features column but no default.
      // Supply a safe default and repair legacy NULLs before enforcing the constraint.
      await databasePool.query(`ALTER TABLE winscope_score_shot_predictions
        ALTER COLUMN features SET DEFAULT '{}'::jsonb`);
      await databasePool.query(`UPDATE winscope_score_shot_predictions SET features='{}'::jsonb WHERE features IS NULL`);
      await databasePool.query(`ALTER TABLE winscope_score_shot_predictions ALTER COLUMN features SET NOT NULL`);
      // Legacy installations may have a required confidence column that the current
      // Score Shot INSERT does not populate. Make it nullable only when it exists.
      await databasePool.query(`DO $$ BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=current_schema()
          AND table_name='winscope_score_shot_predictions' AND column_name='confidence') THEN
          ALTER TABLE winscope_score_shot_predictions ALTER COLUMN confidence DROP NOT NULL;
        END IF;
      END $$`);
      // The write path uses ON CONFLICT(fixture_id, match_date). Normalize duplicate
      // legacy rows first, then guarantee that exact conflict target exists.
      await databasePool.query(`WITH ranked AS (
        SELECT ctid, ROW_NUMBER() OVER (PARTITION BY fixture_id, match_date
          ORDER BY created_at DESC NULLS LAST, ctid DESC) AS rn
        FROM winscope_score_shot_predictions WHERE fixture_id IS NOT NULL AND match_date IS NOT NULL
      ) DELETE FROM winscope_score_shot_predictions t USING ranked r WHERE t.ctid=r.ctid AND r.rn>1`);
      await databasePool.query("CREATE UNIQUE INDEX IF NOT EXISTS winscope_score_shot_fixture_date_uidx ON winscope_score_shot_predictions(fixture_id, match_date)");
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_score_shot_date_idx ON winscope_score_shot_predictions(match_date, selection_score DESC, kickoff_at)");
      // SCORE SHOT JOB QUEUE: shared by every Render instance; jobs survive browser disconnects and process restarts.
      await databasePool.query(`CREATE TABLE IF NOT EXISTS winscope_score_shot_jobs (
        job_id TEXT PRIMARY KEY,
        match_date DATE NOT NULL,
        source TEXT NOT NULL DEFAULT 'manual',
        schedule_key TEXT,
        status TEXT NOT NULL DEFAULT 'queued',
        phase TEXT NOT NULL DEFAULT 'queued',
        progress JSONB NOT NULL DEFAULT '{}'::jsonb,
        error TEXT,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        started_at TIMESTAMPTZ,
        finished_at TIMESTAMPTZ
      )`);
      await databasePool.query("CREATE UNIQUE INDEX IF NOT EXISTS winscope_score_shot_jobs_active_date_uidx ON winscope_score_shot_jobs(match_date) WHERE status IN ('queued','running')");
      await databasePool.query("ALTER TABLE winscope_score_shot_jobs ADD COLUMN IF NOT EXISTS schedule_key TEXT");
      // A lease token fences off a worker that wakes up after another Render instance reclaimed its job.
      await databasePool.query("ALTER TABLE winscope_score_shot_jobs ADD COLUMN IF NOT EXISTS lease_token TEXT");
      await databasePool.query("CREATE UNIQUE INDEX IF NOT EXISTS winscope_score_shot_jobs_schedule_uidx ON winscope_score_shot_jobs(schedule_key) WHERE schedule_key IS NOT NULL");
      await databasePool.query("CREATE INDEX IF NOT EXISTS winscope_score_shot_jobs_status_created_idx ON winscope_score_shot_jobs(status,created_at)");
      const [analysisRows, couponRows, sentRows, predictionRows, livePredictionRows, dailyRunRows, goalTrackingRows] = await Promise.all([
        databasePool.query("SELECT payload FROM winscope_archive WHERE category = 'analysis' ORDER BY id DESC LIMIT 1000"),
        databasePool.query("SELECT payload FROM winscope_archive WHERE category = 'coupon' ORDER BY id DESC LIMIT 50"),
        databasePool.query("SELECT fixture_id, coupon_type, market, match_date FROM winscope_telegram_delivery_sent"),
        databasePool.query("SELECT * FROM winscope_predictions ORDER BY created_at DESC LIMIT 500"),
        databasePool.query("SELECT * FROM winscope_live_predictions ORDER BY created_at DESC LIMIT 500"),
        databasePool.query("SELECT match_date::text, status, result, error, started_at, finished_at FROM winscope_daily_analysis_runs ORDER BY match_date DESC LIMIT 30"),
        databasePool.query("SELECT fixture_id,home_team,away_team,league,source_label,last_score FROM winscope_goal_alert_tracking")
      ]);
      archives.analyses = dedupeAnalysisArchiveRows(analysisRows.rows.map(row => row.payload)).slice(0,1000);
      for (const row of dailyRunRows.rows) dailyAnalysisRunCache.set(String(row.match_date).slice(0,10), {
        date:String(row.match_date).slice(0,10), status:row.status, result:row.result || null,
        error:row.error || null, startedAt:row.started_at, finishedAt:row.finished_at
      });
      archives.coupons = couponRows.rows.map(row => row.payload);
      let couponBackfilled = 0;
      for (const archivedCoupon of archives.coupons) {
        const picks = Array.isArray(archivedCoupon?.picks) ? archivedCoupon.picks : [];
        const couponKey = String(archivedCoupon?.draftId || `${archivedCoupon?.date || "unknown"}:${archivedCoupon?.type || "coupon"}:${archivedCoupon?.createdAt || ""}`);
        for (const pick of picks) {
          const fixtureId = Number(pick?.fixtureId || pick?.fixture_id || 0);
          const market = String(pick?.market || pick?.mainPick || "").trim();
          if (!fixtureId || !market || !pick?.home || !pick?.away) continue;
          const result = await databasePool.query(
            `INSERT INTO winscope_coupon_predictions
              (coupon_key,coupon_type,fixture_id,home_team,away_team,league,market,start_score,match_date,created_at)
             VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,COALESCE($10::timestamptz,NOW()))
             ON CONFLICT(coupon_key,fixture_id,market) DO NOTHING`,
            [couponKey, String(archivedCoupon.type || "prematch"), fixtureId, String(pick.home), String(pick.away),
             String(pick.league || ""), market, String(pick.currentScore || pick.startScore || "0-0"),
             String(archivedCoupon.date || "").slice(0,10) || null, archivedCoupon.createdAt || null]
          );
          couponBackfilled += result.rowCount;
        }
      }
      console.log(`[Coupon tracking] Arşivden takip kaydı aktarıldı: ${couponBackfilled}`);
      predictionTracking.push(...predictionRows.rows.map(row => ({
        fixtureId:Number(row.fixture_id), home:row.home_team, away:row.away_team,
        predictedHT:row.predicted_ht, predictedFT:row.predicted_ft, alternativeFT:row.alternative_ft,
        actualHT:row.actual_ht, actualFT:row.actual_ft, exactFT:row.exact_ft, exactHT:row.exact_ht,
        matchDate:row.match_date, settled:Boolean(row.settled_at), createdAt:row.created_at
      })));
      livePredictionTracking.push(...livePredictionRows.rows.map(row => ({
        fixtureId:Number(row.fixture_id), home:row.home_team, away:row.away_team,
        market:row.market, league:row.league, matchDate:row.match_date, startScore:row.start_score,
        minute:row.minute, actualScore:row.actual_score, outcome:row.outcome,
        settled:Boolean(row.settled_at), createdAt:row.created_at
      })));
      // Gol takibi kalıcı tablodan geri yüklenir; Render yeniden başlasa da skor değişimleri kaçmaz.
      for (const row of goalTrackingRows.rows) {
        const id = Number(row.fixture_id);
        if (!id) continue;
        const lastScore = String(row.last_score || "0-0");
        goalTrackedFixtures.set(id, { home:row.home_team, away:row.away_team, league:row.league,
          sourceLabel:row.source_label || "Canlı maç takibi", baselineScore:lastScore });
        goalScoreCache.set(id, lastScore);
      }
      console.log(`[GOOOOL TRACKING RESTORE] active=${goalTrackedFixtures.size}`);
      // Daha önce Telegram'a gönderilmiş canlı maç/pazarları yeniden başlatmada da engelle.
      for (const row of livePredictionRows.rows) {
        if (row.fixture_id && row.market) autoSentFixtureKeys.add(`next-goal:${Number(row.fixture_id)}:${String(row.market)}`);
      }
      for (const row of sentRows.rows) {
        telegramSentKeys.add(telegramDeliveryKey(row.fixture_id, row.coupon_type, row.market));
        if (row.coupon_type && row.match_date) {
          const matchDate = row.match_date instanceof Date ? row.match_date.toISOString().slice(0, 10) : String(row.match_date).slice(0, 10);
          autoSentFixtureKeys.add(autoLivePickKey(row.coupon_type, matchDate, { fixtureId: row.fixture_id, market: row.market }));
        }
      }
      console.log(`[Archive] PostgreSQL arşivi yüklendi: analyses=${archives.analyses.length}, coupons=${archives.coupons.length}`);
    } catch (error) {
      console.error(`[Archive] PostgreSQL başlatılamadı; servis bellek içi arşivle devam edecek: ${error.message}`);
    }
  })();
}
function dedupeAnalysisArchiveRows(rows = []) {
  const byFixture = new Map();
  for (const row of rows) {
    const analysis = row?.analysis || row || {};
    const firstPick = Array.isArray(row?.picks) ? row.picks[0] : null;
    const fixtureId = Number(
      row?.fixture_id ?? row?.fixtureId ??
      analysis?.fixtureId ?? analysis?.fixture_id ??
      firstPick?.fixtureId ?? firstPick?.fixture_id ?? 0
    );
    const matchDate = String(
      row?.match_date ?? row?.matchDate ?? row?.date ??
      analysis?.matchDate ?? analysis?.match_date ?? ""
    ).slice(0,10);
    const home = String(row?.home_team ?? row?.home ?? analysis?.home ?? firstPick?.home ?? "")
      .toLocaleLowerCase("en").trim();
    const away = String(row?.away_team ?? row?.away ?? analysis?.away ?? firstPick?.away ?? "")
      .toLocaleLowerCase("en").trim();
    const key = fixtureId ? `fixture:${fixtureId}` : `teams:${matchDate}|${home}|${away}`;
    const stamp = Date.parse(row?.created_at || row?.createdAt || analysis?.created_at || "") || 0;
    const previous = byFixture.get(key);
    // API/DB rows are newest-first; retain the first row when timestamps are absent/equal.
    if (!previous || stamp > previous.stamp) byFixture.set(key, { row, stamp });
  }
  return [...byFixture.values()]
    .sort((a,b)=>b.stamp-a.stamp)
    .map(x=>x.row);
}
