async function archiveProviderFixtures(pathname, payload) {
  const pathOnly = String(pathname || "").split("?")[0];
  if (pathOnly !== "/fixtures") return { saved: 0, skipped: true };
  const rows = Array.isArray(payload?.response) ? payload.response : [];
  if (!rows.length || !databasePool) return { saved: 0, skipped: !databasePool };
  try {
    await archiveDatabaseReady;
    const result = await databasePool.query(`
      INSERT INTO winscope_fixture_archive
        (fixture_id, match_date, kickoff_at, status, home_team, away_team, league,
         payload, source_endpoint, first_seen_at, last_seen_at)
      SELECT
        NULLIF(item->'fixture'->>'id','')::bigint,
        NULLIF(left(item->'fixture'->>'date',10),'')::date,
        NULLIF(item->'fixture'->>'date','')::timestamptz,
        NULLIF(item->'fixture'->'status'->>'short',''),
        NULLIF(item->'teams'->'home'->>'name',''),
        NULLIF(item->'teams'->'away'->>'name',''),
        NULLIF(item->'league'->>'name',''),
        item,
        $2,
        NOW(),
        NOW()
      FROM jsonb_array_elements($1::jsonb) AS x(item)
      WHERE NULLIF(item->'fixture'->>'id','') IS NOT NULL
      ON CONFLICT (fixture_id) DO UPDATE SET
        match_date = COALESCE(EXCLUDED.match_date, winscope_fixture_archive.match_date),
        kickoff_at = COALESCE(EXCLUDED.kickoff_at, winscope_fixture_archive.kickoff_at),
        status = COALESCE(EXCLUDED.status, winscope_fixture_archive.status),
        home_team = COALESCE(EXCLUDED.home_team, winscope_fixture_archive.home_team),
        away_team = COALESCE(EXCLUDED.away_team, winscope_fixture_archive.away_team),
        league = COALESCE(EXCLUDED.league, winscope_fixture_archive.league),
        payload = winscope_fixture_archive.payload || EXCLUDED.payload,
        source_endpoint = EXCLUDED.source_endpoint,
        last_seen_at = NOW()
    `, [JSON.stringify(rows), String(pathname || "")]);
    return { saved: result.rowCount || 0 };
  } catch (error) {
    console.error(`[Fixture archive] Kayıt hatası: ${error.message}`);
    return { saved: 0, error: error.message };
  }
}

async function archiveProviderOdds(pathname, payload) {
  const pathOnly = String(pathname || "").split("?")[0];
  // Yalnızca maç önü oranları arşivlenir; /odds/live bilerek dışarıda tutulur.
  if (pathOnly !== "/odds") return { saved: 0, skipped: true };
  const rows = Array.isArray(payload?.response) ? payload.response : [];
  if (!rows.length || !databasePool) return { saved: 0, skipped: !databasePool };

  let client;
  let transactionOpen = false;
  try {
    await archiveDatabaseReady;
    client = await databasePool.connect();
    await client.query("BEGIN");
    transactionOpen = true;
    const serializedRows = JSON.stringify(rows);

    // Eşzamanlı arşiv yazımlarını fixture bazında sıraya al.
    await client.query(`
      WITH incoming AS (
        SELECT DISTINCT NULLIF(item->'fixture'->>'id','')::bigint AS fixture_id
        FROM jsonb_array_elements($1::jsonb) AS x(item)
        WHERE NULLIF(item->'fixture'->>'id','') IS NOT NULL
      )
      SELECT pg_advisory_xact_lock(fixture_id)
      FROM incoming
      ORDER BY fixture_id
    `, [serializedRows]);

    // Aynı fixture + aynı JSONB payload tekrar yazılmaz; değişen payload
    // yeni oran snapshot'ı olarak korunur. Mevcut kayıtlar silinmez.
    const result = await client.query(`
      WITH incoming AS (
        SELECT DISTINCT
          NULLIF(item->'fixture'->>'id','')::bigint AS fixture_id,
          item AS payload
        FROM jsonb_array_elements($1::jsonb) AS x(item)
        WHERE NULLIF(item->'fixture'->>'id','') IS NOT NULL
      )
      INSERT INTO winscope_fixture_odds_archive
        (fixture_id, payload, source_endpoint, captured_at)
      SELECT i.fixture_id, i.payload, $2, NOW()
      FROM incoming i
      WHERE NOT EXISTS (
        SELECT 1 FROM winscope_fixture_odds_archive a
        WHERE a.fixture_id = i.fixture_id AND a.payload = i.payload
      )
    `, [serializedRows, String(pathname || "")]);

    await client.query("COMMIT");
    transactionOpen = false;
    return {
      saved: result.rowCount || 0,
      skippedDuplicates: Math.max(0, rows.length - (result.rowCount || 0))
    };
  } catch (error) {
    if (client && transactionOpen) {
      try { await client.query("ROLLBACK"); } catch {}
    }
    console.error(`[Odds archive] Kayıt hatası: ${error.message}`);
    return { saved: 0, error: error.message };
  } finally {
    if (client) client.release();
  }
}

async function saveCouponTracking(coupon) {
  const picks = Array.isArray(coupon?.picks) ? coupon.picks : [];
  const couponKey = String(coupon?.draftId || `${coupon?.date || "unknown"}:${coupon?.type || "coupon"}:${Date.now()}`);
  if (!databasePool) return { saved: 0, persistent: false };
  let saved = 0;
  for (const pick of picks) {
    const fixtureId = Number(pick?.fixtureId || 0);
    const market = String(pick?.market || "").trim();
    if (!fixtureId || !market || !pick?.home || !pick?.away) continue;
    const result = await databasePool.query(
      `INSERT INTO winscope_coupon_predictions
        (coupon_key,coupon_type,fixture_id,home_team,away_team,league,market,start_score,match_date)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)
       ON CONFLICT(coupon_key,fixture_id,market) DO NOTHING`,
      [couponKey, String(coupon.type || "prematch"), fixtureId, String(pick.home), String(pick.away),
       String(pick.league || ""), market, String(pick.currentScore || pick.startScore || "0-0"),
       String(coupon.date || "").slice(0,10) || null]
    );
    saved += result.rowCount;
  }
  return { saved, persistent: true };
}
