app.get("/api/market-shortlist", async (req, res) => {
  const date = String(req.query.date || "");
  const marketKey = String(req.query.market || "");
  const configs = {
    ht05: { label:"İY 0.5 ÜST", pct:"ht05", formOnly:true },
    ht15: { label:"İY 1.5 ÜST", pct:"ht15", formOnly:true },
    btts: { label:"KG VAR", pct:"btts", price:"yesOdd", opposite:"noOdd" },
    ms25: { label:"MS 2.5 ÜST", pct:"ms25", price:"overOdd", opposite:"underOdd" }
  };
  const cfg = configs[marketKey];
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !cfg) {
    return res.status(400).json({ error:"Tarih veya market seçimi geçersiz." });
  }
  try {
    await archiveDatabaseReady;
    const stored = databasePool
      ? (await databasePool.query(
          "SELECT payload FROM winscope_archive WHERE category='analysis' ORDER BY id DESC"
        )).rows.map(row => row.payload)
      : (archives.analyses || []);
    const unique = new Map();
    for (const record of stored) {
      const a = record?.analysis || record;
      const rowDate = String(record?.match_date || a?.matchDate || a?.match_date || "").slice(0,10);
      const fixtureId = Number(record?.fixture_id || a?.fixtureId || a?.fixture_id || 0);
      if (rowDate !== date || !fixtureId || unique.has(fixtureId)) continue;
      const percentages = a?.marketPercentages || {};
      const percent = Number(percentages?.[cfg.pct]?.percent);
      if (!Number.isFinite(percent)) continue;
      let edge = null;
      let bookmaker = "Son 5 + son 10 maç İY formu";
      if (!cfg.formOnly) {
        const marketRows = Array.isArray(a?.rawPrematchMarkets) ? a.rawPrematchMarkets : [];
        const candidates = marketRows.filter(x => String(x.market || "").toUpperCase() === cfg.label);
        candidates.sort((x,y) => Number(/bet365/i.test(y.bookmaker)) - Number(/bet365/i.test(x.bookmaker)));
        const quote = candidates[0];
        const odd = Number(quote?.[cfg.price]);
        const oppositeOdd = Number(quote?.[cfg.opposite]);
        if (!Number.isFinite(odd) || odd < 1.50 || odd > 1.75) continue;
        let marketFairPercent = 100 / odd;
        if (Number.isFinite(oppositeOdd) && oppositeOdd > 1) {
          const inv = 1 / odd, invOpp = 1 / oppositeOdd;
          marketFairPercent = inv / (inv + invOpp) * 100;
        }
        edge = percent - marketFairPercent;
        if (edge < 2) continue;
        bookmaker = quote?.bookmaker || a?.oddsBookmaker || "Kaynak belirtilmedi";
      } else {
        const n5 = Number(percentages?.[cfg.pct]?.sampleSize5 || 0);
        const n10 = Number(percentages?.[cfg.pct]?.sampleSize10 || 0);
        if (n5 < 5 || n10 < 5) continue;
      }
      unique.set(fixtureId, {
        fixtureId,
        home: record?.home_team || a?.home || a?.home_team || "",
        away: record?.away_team || a?.away || a?.away_team || "",
        league: a?.league || record?.league || "",
        market: cfg.label,
        percent,
        edge: edge == null ? null : Number(edge.toFixed(1)),
        bookmaker,
        sampleSize5: Number(percentages?.[cfg.pct]?.sampleSize5 || 0),
        sampleSize10: Number(percentages?.[cfg.pct]?.sampleSize10 || 0)
      });
    }
    const picks = [...unique.values()].sort((a,b) => b.percent-a.percent || b.edge-a.edge);
    res.json({ date, market:cfg.label, count:picks.length, picks, formOnly:Boolean(cfg.formOnly), minEdge:cfg.formOnly?null:2, oddsBand:cfg.formOnly?null:"1.50–1.75" });
  } catch (error) {
    res.status(500).json({ error:error.message });
  }
});

app.get("/api/archives", async (_req, res) => {
  await archiveDatabaseReady;
  const analyses = dedupeAnalysisArchiveRows(archives.analyses || []).slice(0,1000);
  // Eski arşiv kuponlarında 4/5 maç ve rezerv/kadın/genç takımlar kalmış olabilir.
  // Arşiv ekranına yalnızca güncel kurallara uyan kuponları gönder.
  const coupons = (archives.coupons || []).map(coupon => {
    const picks = Array.isArray(coupon?.picks) ? coupon.picks : [];
    const eligible = picks.filter(p => !isExcludedAnalysisCompetition(p));
    return { ...coupon, picks: eligible };
  }).filter(coupon => {
    const picks = Array.isArray(coupon.picks) ? coupon.picks : [];
    const type = String(coupon.type || "").toLowerCase();
    if (type === "live" || type.includes("live")) return picks.length === 1;
    if (type === "surprise" || type.includes("surprise")) return picks.length === 10;
    return picks.length === 3;
  });
  res.json({ analyses, coupons, persistentStorage: Boolean(databasePool) });
});

app.get("/api/match/:id/stats", async (req, res) => {
  try {
    const payload = await cachedProviderRequest(`stats:${req.params.id}`, `/fixtures/statistics?fixture=${encodeURIComponent(req.params.id)}`, 30000);
    res.json({ success: true, stats: payload.response || [] });
  } catch (e) { res.status(502).json({ success: false, error: "İstatistik alınamadı.", detail: e.message, stats: [] }); }
});

// Otomatik Telegram akışı: canlı tek tercih açılışta ve her 20 dakikada;
// günün maç önü kuponu açılışta ve ardından 2 saatte bir. Buton gerekmez.
function turkeyDateString() {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Istanbul", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type)?.value;
  return `${get("year")}-${get("month")}-${get("day")}`;
}
// Günün majör lig analizini sunucu açılışında ve Türkiye tarihi değiştiğinde otomatik başlat.
let dailyAutoScanDate = "";
async function ensureAutomaticDailyAnalysis() {
  const date = turkeyDateString();
  try {
    const existing = await findDailyAnalysisRun(date);
    if (existing?.status === "completed") { dailyAutoScanDate = date; return; }
    if (existing && ["queued","running"].includes(existing.status)) {
      dailyAutoScanDate = date;
      console.log(`[Daily analysis auto] ${date}: ${existing.status} ${existing.current||0}/${existing.total||0}`);
      return;
    }
    // İlk kez, başarısız, önceki Render sürecinde kesilmiş veya watchdog tarafından takılı iş olarak işaretlenmişse yeniden başlat.
    const job = await startDailyAnalysisIfNeeded(date, { force:Boolean(existing && existing.status === "failed") });
    dailyAutoScanDate = date;
    console.log(`[Daily analysis auto] ${date}: ${job.status}${job.status === "completed" ? " (önceden taranmış)" : ""}`);
  } catch (error) {
    dailyAutoScanDate = "";
    console.warn(`[Daily analysis auto] ${date}: ${error.message}`);
  }
}
setTimeout(() => { void ensureAutomaticDailyAnalysis(); }, 45000);
setInterval(() => { void ensureAutomaticDailyAnalysis(); }, 5 * 60 * 1000);

// Maç başlangıcına yakın ilk yarı pazar karşılaştırması:
// T-5 dakika ve 1. dakika pencerelerinde İY 0.5 / İY 1.5 arasından
// maç önü oranı + son 10 / son 5 ilk yarı gol verisi daha güçlü olan TEK pazar seçilir.
let earlyHalfScanInFlight = false;
const earlyHalfSent = new Set();
async function runEarlyFirstHalfPick() {
  if (earlyHalfScanInFlight) return;
  earlyHalfScanInFlight = true;
  try {
    const date = turkeyDateString();
    const [dayPayload, livePayload] = await Promise.all([
      cachedProviderRequest(`early-ht-fixtures:${date}`, `/fixtures?date=${date}&timezone=Europe/Istanbul`, 25000)
        .catch(e => { console.warn(`[EARLY HT FIXTURES] ${e.message}`); return { response: [] }; }),
      cachedProviderRequest('early-ht-live-fixtures', '/fixtures?live=all', 15000)
        .catch(e => { console.warn(`[EARLY HT LIVE FIXTURES] ${e.message}`); return { response: [] }; })
    ]);

    // T-5 yalnızca veri hazırlığıdır. Tahmin yapılmadan GOOOOL takibi başlatılmaz.
    const dayRows = (dayPayload.response || []).map(normalizeProviderMatch);
    const prep = dayRows.filter(f => f.id && f.periodStatus === 'NS' && f.status === 'NS' &&
      !isExcludedAnalysisCompetition(f) && Number(f.homeScore) === 0 && Number(f.awayScore) === 0 &&
      Number.isFinite(Date.parse(f.fixtureDate || '')) && Date.parse(f.fixtureDate) >= Date.now() &&
      Date.parse(f.fixtureDate) - Date.now() <= 5 * 60 * 1000);
    for (const f of prep) {
      if (!f.homeId || !f.awayId) continue;
      await Promise.all([
        cachedProviderRequest(`early-ht-prematch-odds:${f.id}`, `/odds?fixture=${f.id}`, 60000).catch(() => null),
        fetchLiveGoalProfile(f.homeId, f.id),
        fetchLiveGoalProfile(f.awayId, f.id)
      ]);
      console.log(`[EARLY HT PREPARED] fixture=${f.id} window=T-5 notification=false`);
    }

    // İY erken gol tahmin penceresi ilk 10 dakikadır; 10. dakikadan sonra yeni tahmin açılmaz.
    const liveRows = (livePayload.response || []).map(normalizeProviderMatch);
    const fixtures = liveRows.filter(f => {
      const minute = Number(f.minute);
      const total = Number(f.homeScore) + Number(f.awayScore);
      return f.id && f.status === 'LIVE' && f.periodStatus === '1H' &&
        // 10. dakikadan itibaren, yalnızca hâlâ 0-0 olan ilk yarı maçlarını tara.
        // İlk 10 dakikada gol olmuşsa toplam skor filtresi maçı otomatik dışarıda bırakır.
        Number.isFinite(minute) && minute >= 10 && minute <= 45 && isFreshLiveFixture(f) &&
        Number.isFinite(total) && total === 0 && !isExcludedAnalysisCompetition(f);
    });
    let sent = 0;
    for (const fixture of fixtures) {
      try {
        const key = `${date}|${fixture.id}`;
        if (earlyHalfSent.has(key) || !fixture.homeId || !fixture.awayId) continue;
        const [oddsPayload, homeForm, awayForm, statsPayload] = await Promise.all([
          cachedProviderRequest(`early-ht-prematch-odds:${fixture.id}`, `/odds?fixture=${fixture.id}`, 60000)
            .catch(e => { console.warn(`[EARLY HT ODDS] fixture=${fixture.id}: ${e.message}`); return { response: [] }; }),
          fetchLiveGoalProfile(fixture.homeId, fixture.id),
          fetchLiveGoalProfile(fixture.awayId, fixture.id),
          cachedProviderRequest(`early-ht-live-stats:${fixture.id}`, `/fixtures/statistics?fixture=${fixture.id}`, 12000)
            .catch(e => { console.warn(`[EARLY HT STATS] fixture=${fixture.id}: ${e.message}`); return { response: [] }; })
        ]);
        const oddsRow = (oddsPayload.response || []).find(r =>
          Number(r.fixture?.id ?? r.fixture?.fixture?.id ?? r.fixtureId ?? r.id) === Number(fixture.id)
        ) || null;
        const stats = liveStatsMetrics(statsPayload.response || [], fixture);
        const markets = oddsRow ? oddsForFixture(oddsRow) : [];
        const marketFor = name => {
          const rows = markets.filter(x => x.market === name && Number.isFinite(Number(x.probability)));
          return rows.find(x => /bet365/i.test(String(x.bookmaker || ''))) || rows[0] || null;
        };
        const homeMarket = marketFor('EV 0.5 ÜST');
        const awayMarket = marketFor('DEP 0.5 ÜST');

        // Erken gol motorunun zorunlu filtresi: son 5 tamamlanmış maçın
        // İY takım gol yüzdesi %50'yi AŞMALI. Beş geçerli İY kaydı yoksa
        // tahmin üretilmez; eksik veriyi oran/canlı baskı ile telafi etmeyiz.
        const sideScore = (form, market, live) => {
          const h10 = Number(form?.htTeamScoredPct);
          const h5 = Number(form?.recent?.htTeamScoredPct);
          const sample5 = Number(form?.recent?.htSampleSize || 0);
          const has10 = Number.isFinite(h10);
          const has5 = Number.isFinite(h5) && sample5 >= 5;
          if (!has5 || h5 <= 50) return null;
          const profile = has10 ? h10 * 0.35 + h5 * 0.65 : h5;
          const oddsProb = Number(market?.probability);
          const hasOdds = Number.isFinite(oddsProb);
          const pressure = Number(live?.shotsOnTarget || 0) * 12 + Number(live?.totalShots || 0) * 3 + Number(live?.corners || 0) * 5;
          const hasPressure = Boolean(stats.available);
          const parts = [{ value: profile, weight: 0.65 }];
          if (hasOdds) parts.push({ value: oddsProb, weight: 0.20 });
          if (hasPressure) parts.push({ value: Math.min(100, pressure), weight: 0.15 });
          const weight = parts.reduce((sum, item) => sum + item.weight, 0);
          const score = parts.reduce((sum, item) => sum + item.value * item.weight, 0) / weight;
          return { score, profile, pressure, h10: has10 ? h10 : null, h5,
            market, hasOdds, hasPressure, sample10: Number(form?.htSampleSize || 0), sample5 };
        };
        const home = sideScore(homeForm, homeMarket, stats.home);
        const away = sideScore(awayForm, awayMarket, stats.away);
        const sides = [
          home && { ...home, market: 'EV 0.5 ÜST', side: 'EV SAHİBİ', team: fixture.home },
          away && { ...away, market: 'DEP 0.5 ÜST', side: 'DEPLASMAN', team: fixture.away }
        ].filter(Boolean).sort((a,b) => b.score-a.score);

        // Son 5 İY filtresini geçen takım yoksa (veya örneklem eksikse) alarm YOK.
        if (!sides.length) {
          console.log(`[EARLY HT REJECT] fixture=${fixture.id} reason=last5_ht_goal_pct_missing_or_le_50 home5=${homeForm?.recent?.htTeamScoredPct ?? 'NA'} away5=${awayForm?.recent?.htTeamScoredPct ?? 'NA'} homeN=${homeForm?.recent?.htSampleSize ?? 0} awayN=${awayForm?.recent?.htSampleSize ?? 0}`);
          continue;
        }
        const chosen = sides[0];

        // Güven eşiği: zayıf sinyaller (ör. 56.3) erken gol tahmini olarak kaydedilmez.
        const EARLY_HT_MIN_SCORE = 65;
        if (!Number.isFinite(Number(chosen.score)) || Number(chosen.score) < EARLY_HT_MIN_SCORE) {
          console.log(`[EARLY HT REJECT] fixture=${fixture.id} reason=score_below_min score=${Number(chosen.score || 0).toFixed(1)} min=${EARLY_HT_MIN_SCORE}`);
          continue;
        }

        // Bildirimden hemen önce fixture ID ile taze skor doğrulaması yap.
        // Genel canlı liste/cache gecikmişse eski 0-0 skoruyla tahmin açılmasını önler.
        try {
          const verifyPayload = await cachedProviderRequest(
            `early-ht-verify:${fixture.id}:${Date.now()}`,
            `/fixtures?id=${encodeURIComponent(fixture.id)}`,
            0
          );
          const verifiedRow = verifyPayload.response?.[0];
          if (!verifiedRow) {
            console.log(`[EARLY HT REJECT] fixture=${fixture.id} reason=fresh_fixture_missing`);
            continue;
          }
          const verified = normalizeProviderMatch(verifiedRow);
          const verifiedTotal = Number(verified.homeScore) + Number(verified.awayScore);
          if (verified.status !== 'LIVE' || verified.periodStatus !== '1H' ||
              !Number.isFinite(Number(verified.minute)) || Number(verified.minute) < 10 || Number(verified.minute) > 45 ||
              !Number.isFinite(verifiedTotal) || verifiedTotal !== 0) {
            console.log(`[EARLY HT REJECT] fixture=${fixture.id} reason=score_or_period_changed live=${verified.status}/${verified.periodStatus} minute=${verified.minute} score=${verified.homeScore}-${verified.awayScore}`);
            continue;
          }
          Object.assign(fixture, verified);
        } catch (verifyError) {
          console.warn(`[EARLY HT VERIFY ERROR] fixture=${fixture.id}: ${verifyError.message}`);
          continue; // doğrulanamayan skorla tahmin açma
        }

        const deliveryKey = telegramDeliveryKey(fixture.id, 'early_ht', chosen.market);
        if (telegramSentKeys.has(deliveryKey)) { earlyHalfSent.add(key); continue; }
        if (databasePool) {
          try {
            const prior = await databasePool.query(
              `SELECT 1 FROM winscope_telegram_delivery_sent WHERE fixture_id=$1 AND coupon_type=$2 LIMIT 1`,
              [Number(fixture.id), 'early_ht']
            );
            if (prior.rowCount) { earlyHalfSent.add(key); continue; }
          } catch (e) { console.warn(`[EARLY HT DEDUPE CHECK] fixture=${fixture.id}: ${e.message}`); }
        }
        const dataNotes = [
          chosen.h10 != null ? `Son 10 İY gol: %${chosen.h10}` : null,
          chosen.h5 != null ? `Son 5 maç İY takım gol yüzdesi: %${chosen.h5} (5/5 veri)` : null,
          chosen.hasOdds ? 'Maç önü oranı kullanıldı' : 'Maç önü oranı yok',
          chosen.hasPressure ? `Canlı baskı: ${chosen.pressure.toFixed(1)}` : 'Canlı istatistik henüz yok'
        ].filter(Boolean).join(' · ');
        const message = [
          '⚡ WINSCOPE İLK YARI ERKEN GOL TAHMİNİ',
          `🏟️ ${fixture.home} VS ${fixture.away}`,
          `⏱️ Dakika: ${fixture.minute}' | Skor: ${fixture.homeScore || 0}-${fixture.awayScore || 0}`,
          `🎯 TERCİH: ${chosen.market}`,
          `🔥 Analizin öne çıkardığı: ${chosen.side}${chosen.team ? ` (${chosen.team})` : ''}`,
          `📊 Analiz puanı: ${Number(chosen.score || 0).toFixed(1)}`,
          `🧾 Veriler: ${dataNotes || 'Mevcut maç verileri değerlendirildi'}`,
          '📡 Tahmin canlı takip listesine eklendi.',
          'WinScope · Erken gol analizi'
        ].join('\n');
        const result = await sendTelegram(message);
        if (result.sent) {
          earlyHalfSent.add(key);
          telegramSentKeys.add(deliveryKey);
          const earlyGoalTrack = {
            home: fixture.home, away: fixture.away, league: fixture.league || '',
            sourceLabel: `İY erken gol tahmini | ${chosen.market}`,
            baselineScore: `${fixture.homeScore || 0}-${fixture.awayScore || 0}`
          };
          goalTrackedFixtures.set(Number(fixture.id), earlyGoalTrack);
          goalScoreCache.set(Number(fixture.id), earlyGoalTrack.baselineScore);
          await persistGoalTracking(Number(fixture.id), earlyGoalTrack);
          if (databasePool) {
            try {
              await databasePool.query(`INSERT INTO winscope_early_goal_predictions
                (fixture_id,match_date,home_team,away_team,league,market,selected_side,analysis_score,start_score,current_score)
                VALUES($1,$2::date,$3,$4,$5,$6,$7,$8,$9,$9)
                ON CONFLICT(fixture_id) DO NOTHING`,
                [Number(fixture.id),date,fixture.home,fixture.away,fixture.league||"",chosen.market,chosen.side||"",Number(chosen.score||0),earlyGoalTrack.baselineScore]);
            } catch (e) { console.warn(`[EARLY HT TRACK SAVE] fixture=${fixture.id}: ${e.message}`); }
          }
          sent++;
          if (databasePool) {
            try {
              await databasePool.query(
                `INSERT INTO winscope_telegram_delivery_sent(fixture_id, coupon_type, market, match_date, telegram_message_id)
                 VALUES ($1, $2, $3, $4::date, $5) ON CONFLICT (fixture_id, coupon_type, market) DO NOTHING`,
                [Number(fixture.id), 'early_ht', chosen.market, date, result.messageId]
              );
            } catch (e) { console.warn(`[EARLY HT DEDUPE DB] fixture=${fixture.id}: ${e.message}`); }
          }
          console.log(`[EARLY HT SENT] fixture=${fixture.id} minute=${fixture.minute} market=${chosen.market} score=${Number(chosen.score || 0).toFixed(1)} odds=${chosen.hasOdds} stats=${chosen.hasPressure}`);
        } else {
          console.error(`[EARLY HT TELEGRAM NOT SENT] fixture=${fixture.id}: ${result.reason || 'Telegram gönderimi başarısız'}`);
        }
      } catch (e) { console.warn(`[EARLY HT ERROR] fixture=${fixture.id}: ${e.message}`); }
    }
    console.log(`[EARLY HT SCAN] prep=${prep.length} live10plus0-0=${fixtures.length} sent=${sent}`);
  } catch (e) {
    console.error(`[EARLY HT SCAN ERROR] ${e.message}`);
  } finally {
    earlyHalfScanInFlight = false;
  }
}

async function runAutomaticLivePick() {
  if (autoLiveTaskInFlight) return;
  autoLiveTaskInFlight = true;
  try {
    const result = await buildNextGoalAnalysis({ sendTelegramMessage: true });
    if (result.telegram?.sent) {
      console.log(`[AUTO LIVE] Canlı tercih Telegram'a gönderildi; taranan=${result.scanned}, aday=${result.valueCandidates}`);
    } else if (result.topPick && result.telegram && result.telegram.sent === false) {
      console.error(`[AUTO LIVE] TERCİH VAR AMA TELEGRAM GÖNDERİLEMEDİ: fixture=${result.topPick.fixtureId}, market=${result.topPick.mainPick}, neden=${result.telegram.reason || result.telegram.error || "bilinmiyor"}`);
    } else {
      console.log(`[AUTO LIVE] Tercih bildirimi yok; taranan=${result.scanned}, aday=${result.valueCandidates}, nedenler=${JSON.stringify(result.reasonSummary || {})}`);
    }
  } catch (error) {
    console.error(`[AUTO LIVE ERROR] ${error.message}`);
  } finally {
    autoLiveTaskInFlight = false;
  }
}

const dailyAnalysisCouponRefreshStarted = new Map();
const dailyAnalysisCouponInFlight = new Set();
const dailyAnalysisCouponSentMemory = new Map();

function turkeyClockParts() {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone:"Europe/Istanbul", hour:"2-digit", minute:"2-digit", hourCycle:"h23"
  }).formatToParts(new Date());
  const get = type => Number(parts.find(p=>p.type===type)?.value || 0);
  return { hour:get("hour"), minute:get("minute") };
}

async function dailyAnalysisRowsForCoupon(date) {
  if (databasePool) {
    await archiveDatabaseReady;
    const q = await databasePool.query(`
      SELECT DISTINCT ON (COALESCE(payload->>'fixture_id', payload->'analysis'->>'fixtureId'))
        payload
      FROM winscope_archive
      WHERE category='analysis'
        AND COALESCE(payload->>'match_date', payload->'analysis'->>'matchDate')=$1
      ORDER BY COALESCE(payload->>'fixture_id', payload->'analysis'->>'fixtureId'),
               id DESC
    `,[date]);
    return q.rows.map(r=>r.payload?.analysis || r.payload).filter(Boolean);
  }
  const byFixture = new Map();
  for (const row of archives.analyses || []) {
    const a = row?.analysis || row;
    if (String(a?.matchDate || row?.match_date || "").slice(0,10)!==date) continue;
    const id=Number(a?.fixtureId || row?.fixture_id || 0);
    if (id && !byFixture.has(id)) byFixture.set(id,a);
  }
  return [...byFixture.values()];
}

async function sendDailyAnalysisTopThree(session, date) {
  const key=`${date}:${session}`;
  if (dailyAnalysisCouponInFlight.has(key)) return;
  dailyAnalysisCouponInFlight.add(key);
  try {
    if (databasePool) {
      await archiveDatabaseReady;
      const sent=await databasePool.query(
        "SELECT 1 FROM winscope_daily_analysis_coupon_sessions WHERE match_date=$1::date AND session=$2",
        [date,session]
      );
      if (sent.rowCount) {
        console.log(`[DAILY ANALYSIS 3] ${key} zaten gönderilmiş; tekrar yok.`);
        return;
      }
    } else if (dailyAnalysisCouponSentMemory.has(key)) return;

    const job=await findDailyAnalysisRun(date);
    if (!job || job.status!=="completed") {
      console.log(`[DAILY ANALYSIS 3] ${key} beklemede; analiz durumu=${job?.status || "yok"}.`);
      return;
    }

    const rows=await dailyAnalysisRowsForCoupon(date);
    const fixturePayload=await cachedProviderRequest(`fixtures:${date}`,`/fixtures?date=${date}&timezone=Europe/Istanbul`,30000);
    const upcoming=new Set((fixturePayload.response||[]).map(normalizeProviderMatch)
      .filter(m=>String(m.status||"").toUpperCase()==="NS").map(m=>Number(m.id)));
    const alreadyUsed=new Set();
    if (session==="second") {
      if (databasePool) {
        const prior=await databasePool.query(
          "SELECT picks FROM winscope_daily_analysis_coupon_sessions WHERE match_date=$1::date AND session='early'",
          [date]
        );
        for (const r of prior.rows) for (const p of (r.picks||[])) alreadyUsed.add(Number(p.fixtureId));
      } else {
        for (const p of dailyAnalysisCouponSentMemory.get(`${date}:early`)||[]) alreadyUsed.add(Number(p.fixtureId));
      }
    }
    const valid=rows.map(a=>({...a,_couponEvidence:dailyCouponEvidence(a)})).filter(a=>
      Number(a.fixtureId)>0 && upcoming.has(Number(a.fixtureId)) &&
      !alreadyUsed.has(Number(a.fixtureId)) &&
      ["KG VAR","MS 2.5 ÜST"].includes(String(a.mainPick||"")) &&
      Boolean(a._couponEvidence)
    );
    const deduped=[...new Map(valid.map(a=>[Number(a.fixtureId),a])).values()];
    deduped.sort((a,b)=>
      Number(b._couponEvidence.tier)-Number(a._couponEvidence.tier) ||
      Number(b._couponEvidence.score)-Number(a._couponEvidence.score) ||
      Number(b.marketProbability||0)-Number(a.marketProbability||0) ||
      Number(b.formSupport||0)-Number(a.formSupport||0)
    );
    // Her otomatik kupon tam iki farklı maçtan oluşur; yeterli aday yoksa kupon zorlanmaz.
    const chosen=deduped.slice(0,2);
    if (chosen.length<2) {
      console.warn(`[DAILY ANALYSIS COUPON] ${key} gönderilmedi; güvenilir ve başlamamış aday=${chosen.length}/2.`);
      return;
    }
    const sessionLabel=session==="early"?"GÜVENİLİR KUPON":"ALTERNATİF KUPON";
    const lines=[`🤖 WINSCOPE ${sessionLabel} · 2 MAÇ`,`Tarih: ${date}`,"","Seçimler Günün Analizleri içindeki en yüksek doğrulanmış seçim puanına göre yapıldı.",""];
    chosen.forEach((a,i)=>{
      lines.push(`${i+1}. ${a.home} VS ${a.away}`);
      lines.push(`Ana tercih: ${a.mainPick}`);
      lines.push(`Tahmin İY / MS: ${a.halfTimeScore || "—"} / ${a.fullTimeScore || "—"}`);
      lines.push(`Lig: ${a.league || "—"}`,"");
    });
    lines.push("Not: Yalnızca başlamamış, oran ve son 5 maç formu desteği bulunan analizler seçildi. Sayısal oran gösterilmez; başarı garantisi yoktur.");
    const picks=chosen.map(a=>({
      fixtureId:Number(a.fixtureId),home:a.home,away:a.away,league:a.league,
      market:a.mainPick,startScore:"0-0",currentScore:"0-0",
      predictedHalfTimeScore:a.halfTimeScore||null,predictedFullTimeScore:a.fullTimeScore||null
    }));
    const sent=await sendTelegram(lines.join("\n"));
    if (!sent.sent) {
      console.warn(`[DAILY ANALYSIS 3] ${key} Telegram gönderilemedi: ${sent.reason||"bilinmeyen neden"}`);
      return;
    }
    if (databasePool) {
      await databasePool.query(
        `INSERT INTO winscope_daily_analysis_coupon_sessions(match_date,session,picks,telegram_message_id)
         VALUES($1::date,$2,$3::jsonb,$4) ON CONFLICT(match_date,session) DO NOTHING`,
        [date,session,JSON.stringify(picks),sent.messageId]
      );
    }
    dailyAnalysisCouponSentMemory.set(key,picks);
    const trackingCoupon={draftId:`daily-analysis-${key}`,date,type:`daily3_${session}`,picks,autoGenerated:true};
    await saveCouponTracking(trackingCoupon).catch(e=>console.warn(`[DAILY ANALYSIS 3] takip kaydı: ${e.message}`));
    await saveArchiveItem("coupon",{date,type:`daily3_${session}`,picks,createdAt:new Date().toISOString()});
    console.log(`[DAILY ANALYSIS COUPON SENT] session=${session} date=${date} legs=2 fixtures=${picks.map(p=>p.fixtureId).join(",")} telegramMessageId=${sent.messageId}`);
  } catch(error) {
    console.error(`[DAILY ANALYSIS COUPON ERROR] ${key}: ${error.message}`);
  } finally {
    dailyAnalysisCouponInFlight.delete(key);
  }
}

async function runDailyAnalysisCouponSchedule() {
  const date=turkeyDateString();
  const {hour,minute}=turkeyClockParts();
  const now=hour*60+minute;
  const sessions=[
    {key:"early",refreshAt:9*60+15,sendAt:10*60},
    {key:"second",refreshAt:15*60+15,sendAt:16*60}
  ];
  for (const session of sessions) {
    const refreshKey=`${date}:${session.key}`;
    const refreshAlreadyStarted=dailyAnalysisCouponRefreshStarted.has(refreshKey);
    if (now>=session.refreshAt && now<session.sendAt && !refreshAlreadyStarted) {
      dailyAnalysisCouponRefreshStarted.set(refreshKey,Date.now());
      try {
        const job=await startDailyAnalysisIfNeeded(date);
        console.log(`[DAILY ANALYSIS 3 REFRESH] session=${session.key} date=${date} status=${job.status}`);
        // Bu oturum için tek otomatik tarama. Başarısız olursa manuel yeniden analiz kullanılabilir.
      } catch(error) {
        console.error(`[DAILY ANALYSIS 3 REFRESH ERROR] ${refreshKey}: ${error.message}`);
      }
    }
    // If the analysis is still running or fewer than two qualified matches exist,
    // retry every five minutes until the end of the local day; never manufacture a pick.
    const lastAttempt=dailyAnalysisCouponRefreshStarted.get(`${refreshKey}:send`)||0;
    if (now>=session.sendAt && now<24*60 && Date.now()-lastAttempt>=5*60*1000) {
      dailyAnalysisCouponRefreshStarted.set(`${refreshKey}:send`,Date.now());
      await sendDailyAnalysisTopThree(session.key,date);
    }
  }
}

setTimeout(()=>{ void runDailyAnalysisCouponSchedule(); },30000);
setInterval(()=>{ void runDailyAnalysisCouponSchedule(); },30000);

const autoDailyCouponMemory = new Map();
// AI kuponları artık yalnızca kullanıcı "Günün Yapay Zekâ Kuponları" düğmesine bastığında gönderilir.
// Otomatik zamanlayıcı kapalıdır; arka plan isteği Telegram'a kupon gönderemez.

async function runAutomaticDailyCoupon() {
  if (autoPrematchTaskInFlight) return;
  autoPrematchTaskInFlight = true;
  const date = turkeyDateString();
  const couponType = "prematch";
  let claimed = false;
  try {
    await archiveDatabaseReady;
    if (databasePool) {
      // Bir kez başarılı gönderimden sonra aynı gün tekrar kupon gönderme.
      // NO_MATCHES / FAILED durumları 90 dakika sonra güvenli biçimde yeniden denenir.
      const claim = await databasePool.query(`
        INSERT INTO winscope_auto_coupon_runs(match_date,coupon_type,status,attempts,last_attempt_at,updated_at)
        VALUES($1::date,$2,'running',1,NOW(),NOW())
        ON CONFLICT(match_date,coupon_type) DO UPDATE SET
          status='running',attempts=winscope_auto_coupon_runs.attempts+1,
          last_attempt_at=NOW(),updated_at=NOW(),error=NULL
        WHERE (winscope_auto_coupon_runs.status IN ('no_matches','failed')
               AND winscope_auto_coupon_runs.last_attempt_at < NOW()-INTERVAL '90 minutes')
           OR (winscope_auto_coupon_runs.status='running'
               AND winscope_auto_coupon_runs.last_attempt_at < NOW()-INTERVAL '20 minutes')
        RETURNING match_date`, [date,couponType]);
      claimed = Boolean(claim.rowCount);
    } else {
      const prior = autoDailyCouponMemory.get(date);
      if (!prior || (prior.status !== "sent" && Date.now()-prior.at >= 90*60*1000)) {
        autoDailyCouponMemory.set(date,{status:"running",at:Date.now()});
        claimed = true;
      }
    }
    if (!claimed) return;

    console.log(`[AUTO DAILY] START date=${date}`);
    const result = await createCouponByMode(date, "prematch", { automatic: true });
    const delivered = Boolean(result.telegram?.sent || result.telegram?.duplicateSuppressed);
    const status = result.status === "READY" && delivered ? "sent" : result.status === "NO_MATCHES" ? "no_matches" : "failed";
    if (databasePool) {
      await databasePool.query(`UPDATE winscope_auto_coupon_runs
        SET status=$3,telegram_message_id=$4,result=$5::jsonb,error=$6,updated_at=NOW()
        WHERE match_date=$1::date AND coupon_type=$2`,
        [date,couponType,status,result.telegram?.messageId||null,JSON.stringify({status:result.status,picks:result.picks||[],telegram:result.telegram||null}),
         status === "sent" ? null : (result.message||result.telegram?.reason||result.telegram?.error||result.detail||result.status)]);
    } else autoDailyCouponMemory.set(date,{status,at:Date.now()});
    console.log(`[AUTO DAILY] END date=${date} status=${status} picks=${result.picks?.length||0} telegram=${delivered}`);
  } catch (error) {
    console.error(`[AUTO DAILY ERROR] date=${date}: ${error.stack||error.message}`);
    if (databasePool && claimed) {
      await databasePool.query(`UPDATE winscope_auto_coupon_runs SET status='failed',error=$3,updated_at=NOW()
        WHERE match_date=$1::date AND coupon_type=$2`,[date,couponType,error.message]).catch(()=>{});
    } else if (claimed) autoDailyCouponMemory.set(date,{status:"failed",at:Date.now()});
  } finally {
    autoPrematchTaskInFlight = false;
  }
}

// Render ücretsiz servis uyandığında da ilk otomatik denemeyi yapar; uygun aday yoksa 90 dk sonra tekrarlar.
setTimeout(() => { void runAutomaticDailyCoupon(); }, 90000);
setInterval(() => { void runAutomaticDailyCoupon(); }, 90 * 60 * 1000);

// Canlı tek tercih otomatik taraması: tarama tamamlanınca 90 saniyelik döngü; eşzamanlı tarama engellenir.
setTimeout(() => { void runAutomaticLivePick(); }, 20000);
// Günün maç önü kuponu ayrı ve kalıcı kilitli runAutomaticDailyCoupon zamanlayıcısıyla üretilir.
setInterval(() => { void runAutomaticLivePick(); }, 60 * 1000);
// İlk yarı erken sinyali: maç önü veri hazırlığı + canlı 1-10. dakika tahmin taraması.
setTimeout(() => { void runEarlyFirstHalfPick(); }, 25000);
setInterval(() => { void runEarlyFirstHalfPick(); }, 60 * 1000);
setTimeout(() => { void scanSurpriseScenarios(); }, 45000);
setInterval(() => { void scanSurpriseScenarios(); }, 10 * 60 * 1000);

// Takip edilen canlı maçların skorunu 45 saniyede bir kontrol et.
// Canlı listede görünmeyen fixture'lar ayrıca ID ile sorgulanır; sessizce atlanmaz.
setInterval(async () => {
  if (goalScanInFlight || goalTrackedFixtures.size === 0) return;
  goalScanInFlight = true;
  const trackedCount = goalTrackedFixtures.size;
  let matchedCount = 0;
  let changedCount = 0;
  try {
    const payload = await cachedProviderRequest("liveList:goal-alert", "/fixtures?live=all", 20_000);
    const liveMatches = (payload.response || []).map(normalizeProviderMatch);
    const liveById = new Map(liveMatches.map(m => [Number(m.id), m]));

    for (const [fixtureId, tracked] of goalTrackedFixtures.entries()) {
      let match = liveById.get(fixtureId);
      const isEarlyHalfPick = /İY erken gol tahmini \| (EV 0\.5 ÜST|DEP 0\.5 ÜST|İY 0\.5 ÜST)/i.test(String(tracked.sourceLabel || ''));

      // Erken İY tahminlerinde genel canlı liste eski skor döndürebilir.
      // Bu kayıtları her turda fixture ID ile tazeleyerek 0-0/0-1 uyuşmazlığını önle.
      if (isEarlyHalfPick) {
        try {
          const direct = await cachedProviderRequest(
            `early-ht-track:${fixtureId}:${Math.floor(Date.now() / 30000)}`,
            `/fixtures?id=${encodeURIComponent(fixtureId)}`,
            0
          );
          const row = direct.response?.[0];
          if (row) match = normalizeProviderMatch(row);
        } catch (lookupError) {
          console.warn(`[EARLY HT FRESH SCORE ERROR] ${fixtureId}: ${lookupError.message}`);
          continue;
        }
      }

      // API'nin genel canlı listesinden düşen takipli maçı fixture ID ile tekrar kontrol et.
      if (!match) {
        try {
          const direct = await cachedProviderRequest(
            `goal-alert-fixture:${fixtureId}`,
            `/fixtures?id=${encodeURIComponent(fixtureId)}`,
            10_000
          );
          const row = direct.response?.[0];
          if (row) match = normalizeProviderMatch(row);
        } catch (lookupError) {
          console.warn(`[GOOOOL FIXTURE LOOKUP ERROR] ${fixtureId}: ${lookupError.message}`);
          continue;
        }
      }

      if (!match) {
        console.warn(`[GOOOOL TRACKING MISS] fixture=${fixtureId}; canlı liste ve ID sorgusunda bulunamadı.`);
        continue;
      }
      matchedCount++;

      const score = `${match.homeScore}-${match.awayScore}`;
      const previous = goalScoreCache.get(fixtureId) ?? tracked.baselineScore ?? score;
      const earlyPickMatch = String(tracked.sourceLabel || "").match(/İY erken gol tahmini \| (EV 0\.5 ÜST|DEP 0\.5 ÜST|İY 0\.5 ÜST)/i);
      const earlyStatus = String(match.periodStatus || match.status || "").toUpperCase();
      if (earlyPickMatch) {
        const [nowHome, nowAway] = score.split("-").map(Number);
        const [prevHome, prevAway] = previous.split("-").map(Number);
        const firstHalfActive = ["1H","LIVE"].includes(earlyStatus) && Number(match.minute) <= 45;
        const firstHalfClosed = ["HT","2H","2ND HALF","FT","AET","PEN","CANC","ABD","AWD","WO"].includes(earlyStatus);
        const htHome = match.htHomeScore == null ? null : Number(match.htHomeScore);
        const htAway = match.htAwayScore == null ? null : Number(match.htAwayScore);
        // HT/FT durumunda ilk yarı skoru API'den gelmeden kayıp kararı verme.
        if (firstHalfClosed && (htHome == null || htAway == null)) {
          console.warn(`[EARLY HT SETTLEMENT WAIT] fixture=${fixtureId} reason=halftime_score_missing status=${earlyStatus}`);
          continue;
        }
        const checkHome = firstHalfClosed ? htHome : nowHome;
        const checkAway = firstHalfClosed ? htAway : nowAway;
        const targetScored = earlyPickMatch[1].toUpperCase().startsWith("EV") ? checkHome > 0
          : earlyPickMatch[1].toUpperCase().startsWith("DEP") ? checkAway > 0 : (checkHome + checkAway) > 0;
        if (targetScored && (firstHalfActive || firstHalfClosed)) {
          let goalMinuteText = Number.isFinite(Number(match.minute)) ? `${Number(match.minute)}'` : "Dakika bilgisi alınamadı";
          try {
            const eventPayload = await cachedProviderRequest(`early-goal-events:${fixtureId}:${score}`, `/fixtures/events?fixture=${fixtureId}`, 0);
            const goalEvents = (eventPayload.response || []).filter(ev => /goal/i.test(String(ev.type || "")) && /normal goal|penalty|own goal|goal/i.test(String(ev.detail || "goal")));
            const [ph, pa] = previous.split("-").map(Number);
            const [nh, na] = score.split("-").map(Number);
            const scorerTeam = nh > ph ? String(match.home || tracked.home || "") : String(match.away || tracked.away || "");
            const matchingEvent = goalEvents.filter(ev => !scorerTeam || String(ev.team?.name || "").toLowerCase() === scorerTeam.toLowerCase()).slice(-1)[0]
              || goalEvents.slice(-1)[0];
            if (matchingEvent?.time?.elapsed != null) goalMinuteText = `${matchingEvent.time.elapsed}${matchingEvent.time.extra ? `+${matchingEvent.time.extra}` : ""}'`;
          } catch (eventError) {
            console.warn(`[EARLY HT GOAL EVENT] fixture=${fixtureId}: ${eventError.message}`);
          }
          const wonMessage = `⚽ WINSCOPE ERKEN GOL TAHMİNİ KAZANDI ✅\n🏟️ ${match.home || tracked.home} VS ${match.away || tracked.away}\n📣 Skor: ${previous} → ${score}\n⏱️ GOL DAKİKASI: ${goalMinuteText}\n🎯 ${earlyPickMatch[1]}\nGol gerçekleştiği anda tespit edildi; ilk yarı hedefi tuttu.`;
          // Sonuç kaydı Telegram teslimatından bağımsızdır: bildirim hatası
          // kazanan tahminin veritabanında sonsuza kadar beklemede kalmasına yol açmaz.
          try {
            if (databasePool) await databasePool.query(`UPDATE winscope_early_goal_predictions SET current_score=$2,outcome='won',settled_at=NOW() WHERE fixture_id=$1 AND outcome IS NULL`,[fixtureId,score]);
            const sent = await sendTelegram(wonMessage);
            if (!sent.sent) console.error(`[EARLY HT SETTLEMENT NOT SENT] fixture=${fixtureId}: ${sent.reason||"Telegram error"}`);
            goalTrackedFixtures.delete(fixtureId); goalScoreCache.delete(fixtureId);
            if (databasePool) await databasePool.query("DELETE FROM winscope_goal_alert_tracking WHERE fixture_id=$1",[fixtureId]);
            console.log(`[EARLY HT SETTLED] fixture=${fixtureId} outcome=won score=${score} telegram=${Boolean(sent.sent)}`);
          } catch (settleError) {
            console.error(`[EARLY HT SETTLEMENT ERROR] fixture=${fixtureId}: ${settleError.message}`);
            goalScoreCache.set(fixtureId,score); tracked.baselineScore=score; await persistGoalTracking(fixtureId,tracked);
          }
          continue;
        }
        if (firstHalfClosed && !targetScored) {
          const lostMessage = `⏱️ WINSCOPE ERKEN GOL TAHMİNİ KAYBETTİ\n🏟️ ${match.home || tracked.home} VS ${match.away || tracked.away}\n📊 İlk yarı skoru: ${match.htHomeScore ?? match.homeScore}-${match.htAwayScore ?? match.awayScore}\n🎯 ${earlyPickMatch[1]}\nİlk yarı hedef golü gerçekleşmedi.`;
          const sent = await sendTelegram(lostMessage);
          if (databasePool) await databasePool.query(`UPDATE winscope_early_goal_predictions SET current_score=$2,outcome='lost',settled_at=NOW() WHERE fixture_id=$1 AND outcome IS NULL`,[fixtureId,score]);
          goalTrackedFixtures.delete(fixtureId); goalScoreCache.delete(fixtureId);
          if (databasePool) await databasePool.query("DELETE FROM winscope_goal_alert_tracking WHERE fixture_id=$1",[fixtureId]);
          console.log(`[EARLY HT SETTLED] fixture=${fixtureId} outcome=lost score=${score} telegram=${Boolean(sent.sent)}`);
          continue;
        }
        // Opponent goals do not settle EV/DEP early-goal picks. Keep tracking silently
        // until the selected team scores or the first half closes; never send generic GOOOOL alerts.
        if (score !== previous) {
          changedCount++; goalScoreCache.set(fixtureId,score); tracked.baselineScore=score;
          await persistGoalTracking(fixtureId,tracked);
          if (databasePool) await databasePool.query("UPDATE winscope_early_goal_predictions SET current_score=$2 WHERE fixture_id=$1 AND outcome IS NULL",[fixtureId,score]);
        }
        continue;
      }
      if (score !== previous) {
        changedCount++;
        const earlyPickMatch = null;
        const minuteValue = Number(match.minute);
        const isFirstHalf = String(match.periodStatus || "").toUpperCase() === "1H" ||
          (Number.isFinite(minuteValue) && minuteValue <= 45 && !["HT","2H","FT","AET","PEN"].includes(String(match.periodStatus || "").toUpperCase()));
        const [prevHome, prevAway] = previous.split("-").map(Number);
        const [nowHome, nowAway] = score.split("-").map(Number);
        const previousTotal = prevHome + prevAway;
        const currentTotal = nowHome + nowAway;
        const scoreIncreased = currentTotal > previousTotal;
        const scoreDecreased = currentTotal < previousTotal;
        const earlyPickWon = Boolean(earlyPickMatch && isFirstHalf && scoreIncreased && (
          earlyPickMatch[1].toUpperCase().startsWith("EV") ? nowHome > 0 :
          earlyPickMatch[1].toUpperCase().startsWith("DEP") ? nowAway > 0 : currentTotal > 0
        ));
        const minuteText = Number.isFinite(minuteValue) ? `${minuteValue}'` : "Bilinmiyor";
        const message = scoreDecreased
          ? `🚫 WINSCOPE GOL İPTAL!\n🏆 ${match.league || tracked.league || "Lig"}\n⚽ ${match.home || tracked.home} - ${match.away || tracked.away}\n📣 Skor düzeltildi: ${previous} → ${score}\n⏱️ Dakika: ${minuteText}\n🎯 Önceki gol bildirimi iptal edildi.`
          : earlyPickWon
            ? `⚽ WINSCOPE GOOOOOL — TAHMİN KAZANDI ✅\n🏆 ${match.league || tracked.league || "Lig"}\n⚽ ${match.home || tracked.home} - ${match.away || tracked.away}\n📣 Skor: ${previous} → ${score}\n⏱️ Dakika: ${minuteText}\n🎯 Gerçekleşen tercih: ${earlyPickMatch[1]}`
            : scoreIncreased
              ? `⚽ WINSCOPE GOOOOOL!\n🏆 ${match.league || tracked.league || "Lig"}\n⚽ ${match.home || tracked.home} - ${match.away || tracked.away}\n📣 Skor değişti: ${previous} → ${score}\n⏱️ Dakika: ${minuteText}\n🎯 Takip nedeni: ${tracked.sourceLabel || "Canlı maç takibi"}`
              : `🔄 WINSCOPE SKOR DÜZELTİLDİ\n🏆 ${match.league || tracked.league || "Lig"}\n⚽ ${match.home || tracked.home} - ${match.away || tracked.away}\n📣 Skor: ${previous} → ${score}\n⏱️ Dakika: ${minuteText}`;
        try {
          const sent = await sendTelegram(message);
          if (sent.sent) {
            goalScoreCache.set(fixtureId, score);
            tracked.baselineScore = score;
            if (earlyPickWon) tracked.sourceLabel = `İY erken gol tahmini tamamlandı | ${earlyPickMatch[1]}`;
            await persistGoalTracking(fixtureId, tracked);
            console.log(`[GOOOOL Alert OK] ${fixtureId} ${previous} -> ${score} earlyPickWon=${earlyPickWon}`);
          } else {
            console.error(`[GOOOOL Alert NOT SENT] ${fixtureId}: ${sent.reason || "Telegram gönderimi başarısız"}`);
          }
        } catch (error) {
          console.error(`[GOOOOL Alert Error] ${fixtureId}: ${error.message}`);
        }
      }

      if (["FT", "AET", "PEN", "CANC", "ABD", "AWD", "WO"].includes(String(match.periodStatus || match.status || "").toUpperCase())) {
        goalTrackedFixtures.delete(fixtureId);
        goalScoreCache.delete(fixtureId);
        if (databasePool) await databasePool.query("DELETE FROM winscope_goal_alert_tracking WHERE fixture_id=$1",[fixtureId]).catch(e=>console.warn(`[GOOOOL TRACKING DELETE] ${fixtureId}: ${e.message}`));
        console.log(`[GOOOOL TRACKING CLOSED] fixture=${fixtureId} finalScore=${score}`);
      }
    }
    console.log(`[GOOOOL SCAN] tracked=${trackedCount} matched=${matchedCount} scoreChanges=${changedCount}`);
  } catch (error) {
    console.error(`[GOOOOL Scan Error] ${error.message}`);
  } finally {
    goalScanInFlight = false;
  }
}, 45_000);

let couponSettlementInFlight = false;
async function settleCouponPredictions() {
  if (!databasePool || couponSettlementInFlight) return;
  couponSettlementInFlight = true;
  try {
    // Kontrol edilen ama henüz bitmemiş maçlar 10 dakika sonra tekrar denenir.
    // Böylece ilk 40 eski/kayıp fixture kaydı kuyruğu sonsuza kadar bloke etmez.
    const pending = await databasePool.query(`SELECT tracking_id,fixture_id,market,coupon_type,home_team,away_team,league,telegram_notified_at
      FROM winscope_coupon_predictions
      WHERE settled_at IS NULL
        AND (settlement_checked_at IS NULL OR settlement_checked_at < NOW() - INTERVAL '10 minutes')
        AND ((match_date ~ '^\\d{4}-\\d{2}-\\d{2}$' AND match_date::date <= (NOW() AT TIME ZONE 'Europe/Istanbul')::date)
             OR (match_date IS NULL AND created_at < NOW() - INTERVAL '3 hours'))
      ORDER BY COALESCE(match_date,'') ASC, created_at ASC LIMIT 60`);
    if (!pending.rows.length) return;
    const fixtureGroups = new Map();
    for (const item of pending.rows) {
      const id = Number(item.fixture_id);
      if (!fixtureGroups.has(id)) fixtureGroups.set(id, []);
      fixtureGroups.get(id).push(item);
    }
    for (const [fixtureId, items] of fixtureGroups) {
      try {
        const payload = await cachedProviderRequest(`coupon-settle:${fixtureId}`, `/fixtures?id=${fixtureId}`, 5 * 60 * 1000);
        await databasePool.query(
          `UPDATE winscope_coupon_predictions SET settlement_checked_at=NOW()
           WHERE tracking_id = ANY($1::bigint[]) AND settled_at IS NULL`,
          [items.map(x => x.tracking_id)]
        );
        const row = payload.response?.[0];
        const status = String(row?.fixture?.status?.short || '').toUpperCase();
        if (!row || !['FT','AET','PEN'].includes(status) || row.goals?.home == null || row.goals?.away == null) continue;
        const homeGoals = Number(row.goals.home), awayGoals = Number(row.goals.away);
        const htHome = row.score?.halftime?.home == null ? null : Number(row.score.halftime.home);
        const htAway = row.score?.halftime?.away == null ? null : Number(row.score.halftime.away);
        const actualScore = `${homeGoals}-${awayGoals}`;
        for (const item of items) {
          const result = evaluateTrackedLiveMarket(item.market, homeGoals, awayGoals, htHome, htAway);
          if (result == null) {
            console.warn(`[Coupon tracking] Desteklenmeyen pazar: fixture=${fixtureId} market=${item.market}`);
            continue;
          }
          const outcome = result ? 'won' : 'lost';
          const updated = await databasePool.query(
            `UPDATE winscope_coupon_predictions SET actual_score=$2,outcome=$3,settled_at=NOW()
             WHERE tracking_id=$1 AND settled_at IS NULL RETURNING tracking_id`,
            [item.tracking_id, actualScore, outcome]
          );
          if (!updated.rowCount || outcome !== 'won' || item.telegram_notified_at) continue;
          const marketKey = String(item.market || '').trim().toLocaleLowerCase('tr-TR');
          // Aynı fixture+market birden fazla kupon/tekrar kayıt içinde bulunsa da tek bildirim.
          const claim = await databasePool.query(
            `INSERT INTO winscope_coupon_result_notifications(fixture_id,market_key,status)
             VALUES($1,$2,'sending') ON CONFLICT(fixture_id,market_key) DO NOTHING RETURNING fixture_id`,
            [fixtureId, marketKey]
          );
          if (!claim.rowCount) {
            await databasePool.query(
              'UPDATE winscope_coupon_predictions SET telegram_notified_at=COALESCE(telegram_notified_at,NOW()) WHERE tracking_id=$1',
              [item.tracking_id]
            );
            continue;
          }
          const message = [
            '🏆 WINSCOPE KUPON TERCİHİ KAZANDI!',
            `🏟️ ${item.league || 'Lig bilgisi yok'}`,
            `⚽ ${item.home_team} - ${item.away_team}`,
            `🎯 Kazanan tercih: ${item.market}`,
            `📊 Maç sonucu: ${actualScore}`,
            `📌 Kupon türü: ${item.coupon_type === 'live' ? 'Canlı' : item.coupon_type === 'surprise' ? 'Sürpriz' : 'Maç önü'}`
          ].join('\n');
          try {
            const sent = await sendTelegram(message);
            if (sent.sent) {
              await databasePool.query(
                `UPDATE winscope_coupon_result_notifications SET status='sent',telegram_message_id=$3,sent_at=NOW()
                 WHERE fixture_id=$1 AND market_key=$2`, [fixtureId, marketKey, sent.messageId]
              );
              await databasePool.query(
                'UPDATE winscope_coupon_predictions SET telegram_notified_at=NOW() WHERE tracking_id=$1 AND telegram_notified_at IS NULL',
                [item.tracking_id]
              );
            } else {
              await databasePool.query("DELETE FROM winscope_coupon_result_notifications WHERE fixture_id=$1 AND market_key=$2 AND status='sending'", [fixtureId, marketKey]);
            }
          } catch (telegramError) {
            await databasePool.query("DELETE FROM winscope_coupon_result_notifications WHERE fixture_id=$1 AND market_key=$2 AND status='sending'", [fixtureId, marketKey]);
            console.warn(`[Coupon tracking Telegram] fixture=${fixtureId} market=${marketKey}: ${telegramError.message}`);
          }
        }
      } catch (error) {
        console.warn(`[Coupon tracking settlement] fixture=${fixtureId}: ${error.message}`);
      }
    }
  } finally {
    couponSettlementInFlight = false;
  }
}
